<!--
 * 用户账号管理页面 — 展示用户列表，支持新增/编辑/删除、角色分配、重置密码及多条件检索
 *
 * @path apps\userinfo-web\src\views\system\user\index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * 用户（列表页）
 * <p>用户账号（{@code ydsz_user}）的列表页，消费后端契约 UserAccountController
 * （src/api/userAccount.ts，auto-generated by bash/gen-contract.py）：
 * page() 分页查询用户，支持新增/编辑/删除、角色分配（getUserRoles / assignRoles）、
 * 重置密码；搜索表单由静态字段（用户名/姓名/手机号/状态）与异步选项字段
 * （公司/部门/岗位，因选项需加载后才有，用自定义搜索区承载）组成。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeTableGridOptions } from '@ydsz/plugins/vxe-table';

import { Page, useYDSZModal } from '@ydsz/common-ui';

import {
  ElButton,
  ElMessage,
  ElMessageBox,
  ElOption,
  ElSelect,
  ElTag,
  ElTreeSelect,
} from 'element-plus';
import { h, onMounted, reactive, ref } from 'vue';

import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import { list as companyList } from '#/api/company';
import type { CompanyVO } from '#/api/models';
import { tree as deptTree } from '#/api/department';
import type { DepartmentTreeVO } from '#/api/models';
import { list as postList } from '#/api/post';
import type { PostVO } from '#/api/models';
import { list as roleList } from '#/api/role';
import type { RoleVO } from '#/api/models';
import {
  getUserRoles,
  page,
  remove,
  resetPassword,
} from '#/api/userAccount';
import type { UserAccountVO } from '#/api/models';

import RoleAssign from './role-assign.vue';
import UserForm from './user-form.vue';

defineOptions({ name: 'UserManagement' });

/** 判断用户状态是否启用（契约 status 为数字，1 启用 / 0 禁用） */
function isEnabled(status?: number): boolean {
  return status === 1;
}

// ========== 下拉选项数据（公司/部门/岗位/角色） ==========
const companyOptions = ref<CompanyVO[]>([]);
const deptTreeData = ref<DepartmentTreeVO[]>([]);
const postOptions = ref<PostVO[]>([]);
const roleOptions = ref<RoleVO[]>([]);

/** 部门 id -> 部门名称（树拍平） */
const deptNameMap = new Map<string, string>();
/** 岗位编码 -> 岗位名称（positionCode 与 postCode 对应） */
const postNameMap = new Map<string, string>();

function flattenDeptTree(nodes: DepartmentTreeVO[]) {
  nodes.forEach((node) => {
    if (node.id && node.deptName) {
      deptNameMap.set(node.id, node.deptName);
    }
    if (node.children?.length) {
      flattenDeptTree(node.children);
    }
  });
}

async function loadOptions() {
  try {
    const [companies, depts, posts, roles] = await Promise.all([
      companyList(),
      deptTree(),
      postList(),
      roleList(),
    ]);
    companyOptions.value = companies ?? [];
    deptTreeData.value = depts ?? [];
    postOptions.value = posts ?? [];
    roleOptions.value = roles ?? [];
    deptNameMap.clear();
    flattenDeptTree(deptTreeData.value);
    postNameMap.clear();
    postOptions.value.forEach((post) => {
      if (post.postCode && post.postName) {
        postNameMap.set(post.postCode, post.postName);
      }
    });
  } catch {
    // 错误提示由请求拦截器统一处理
  }
}

onMounted(loadOptions);

/** 自定义搜索区状态（公司/部门/岗位，选项为异步数据无法进入 formOptions 快照） */
const searchForm = reactive({
  companyId: '',
  deptId: '',
  positionCode: '',
});

function handleSearch() {
  gridApi.query();
}

function handleReset() {
  Object.assign(searchForm, { companyId: '', deptId: '', positionCode: '' });
  gridApi.query();
}

const gridOptions: VxeTableGridOptions<UserAccountVO> = {
  columns: [
    { type: 'seq', width: 50, title: '序号' },
    { field: 'username', title: '用户名', width: 120 },
    { field: 'realName', title: '真实姓名', width: 100 },
    { field: 'phone', title: '手机号', width: 130 },
    { field: 'email', title: '邮箱', minWidth: 150 },
    {
      field: 'companyId',
      title: '公司',
      width: 120,
      slots: {
        default: ({ row }) =>
          h(
            'span',
            null,
            companyOptions.value.find((c) => c.id === row.companyId)?.companyName || '-',
          ),
      },
    },
    {
      field: 'deptId',
      title: '部门',
      width: 120,
      slots: {
        default: ({ row }) => h('span', null, deptNameMap.get(row.deptId ?? '') || '-'),
      },
    },
    {
      field: 'positionCode',
      title: '岗位',
      width: 100,
      slots: {
        default: ({ row }) =>
          h('span', null, postNameMap.get(row.positionCode ?? '') || '-'),
      },
    },
    {
      field: 'status',
      title: '状态',
      width: 80,
      slots: {
        default: ({ row }) => {
          const enable = isEnabled(row.status);
          return h(
            ElTag,
            { type: enable ? 'success' : 'danger', size: 'small' },
            () => (enable ? '启用' : '禁用'),
          );
        },
      },
    },
    { field: 'lastLoginAt', title: '最后登录', width: 160 },
    { field: 'createdAt', title: '创建时间', width: 160 },
    {
      field: 'action',
      title: '操作',
      width: 260,
      fixed: 'right',
      slots: {
        default: ({ row }) =>
          h('div', { class: 'flex gap-1' }, [
            h(
              ElButton,
              { size: 'small', link: true, type: 'primary', onClick: () => handleEdit(row) },
              () => '编辑',
            ),
            h(
              ElButton,
              { size: 'small', link: true, type: 'warning', onClick: () => handleAssignRoles(row) },
              () => '分配角色',
            ),
            h(
              ElButton,
              { size: 'small', link: true, type: 'info', onClick: () => handleResetPassword(row) },
              () => '重置密码',
            ),
            h(
              ElButton,
              { size: 'small', link: true, type: 'danger', onClick: () => handleDelete(row) },
              () => '删除',
            ),
          ]),
      },
    },
  ],
  height: 'auto',
  pagerConfig: { pageSize: 20, pageSizes: [10, 20, 50, 100] },
  proxyConfig: {
    ajax: {
      query: async (_page, formValues) => {
        const res = await page({ query: { ...searchForm, ...formValues } });
        return { items: res.data ?? [], total: res.total ?? 0 };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, search: true, zoom: true },
};

const [Grid, gridApi] = useYDSZVxeGrid({
  gridOptions,
  formOptions: {
    schema: [
      {
        component: 'Input',
        componentProps: { placeholder: '用户名' },
        fieldName: 'username',
        label: '用户名',
      },
      {
        component: 'Input',
        componentProps: { placeholder: '真实姓名' },
        fieldName: 'realName',
        label: '真实姓名',
      },
      {
        component: 'Input',
        componentProps: { placeholder: '手机号' },
        fieldName: 'phone',
        label: '手机号',
      },
      {
        component: 'Select',
        componentProps: {
          placeholder: '状态',
          options: [
            { label: '启用', value: '1' },
            { label: '禁用', value: '0' },
          ],
        },
        fieldName: 'status',
        label: '状态',
      },
    ],
    submitOnChange: false,
    collapsed: false,
    collapseTriggerResize: true,
    showCollapseButton: true,
    submitButtonOptions: { content: '搜索' },
    resetButtonOptions: { content: '重置' },
  },
});

// ========== 表单弹窗 ==========
const [UserFormModal, userFormApi] = useYDSZModal({ connectedComponent: UserForm });

function handleAdd() {
  userFormApi.setData({
    companyList: companyOptions.value,
    deptTreeData: deptTreeData.value,
    postList: postOptions.value,
    roleList: roleOptions.value,
  });
  userFormApi.open();
}

function handleEdit(row: UserAccountVO) {
  userFormApi.setData({
    record: row,
    companyList: companyOptions.value,
    deptTreeData: deptTreeData.value,
    postList: postOptions.value,
    roleList: roleOptions.value,
  });
  userFormApi.open();
}

// ========== 角色分配弹窗 ==========
const [RoleAssignModal, roleAssignApi] = useYDSZModal({ connectedComponent: RoleAssign });

async function handleAssignRoles(row: UserAccountVO) {
  if (!row.id) return;
  let selectedRoleIds: string[] = [];
  try {
    selectedRoleIds = (await getUserRoles({ userId: row.id })) ?? [];
  } catch {
    // 错误提示由请求拦截器统一处理
  }
  roleAssignApi.setData({
    userId: row.id,
    username: row.username,
    roleList: roleOptions.value,
    selectedRoleIds,
  });
  roleAssignApi.open();
}

// ========== 重置密码 ==========
async function handleResetPassword(row: UserAccountVO) {
  if (!row.id) return;
  try {
    const { value } = await ElMessageBox.prompt(
      `请输入用户「${row.username ?? ''}」的新密码`,
      '重置密码',
      {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        inputPattern: /.{6,}/,
        inputErrorMessage: '密码至少6位',
      },
    );
    await resetPassword({ userId: row.id, newPassword: value });
    ElMessage.success('密码重置成功');
  } catch {
    // 用户取消或请求失败
  }
}

// ========== 删除 ==========
async function handleDelete(row: UserAccountVO) {
  if (!row.id) return;
  try {
    await ElMessageBox.confirm(
      `确定删除用户「${row.username ?? ''}」吗？`,
      '删除确认',
      { type: 'warning' },
    );
    await remove({ id: row.id });
    ElMessage.success('删除成功');
    gridApi.query();
  } catch {
    // 用户取消或请求失败
  }
}
</script>

<template>
  <Page auto-content-height>
    <div class="flex flex-wrap items-center gap-2 px-4 pt-3">
      <span class="text-sm text-gray-500">更多筛选：</span>
      <ElSelect
        v-model="searchForm.companyId"
        placeholder="公司"
        clearable
        class="w-44"
      >
        <ElOption
          v-for="item in companyOptions"
          :key="item.id"
          :label="item.companyName"
          :value="item.id ?? ''"
        />
      </ElSelect>
      <ElTreeSelect
        v-model="searchForm.deptId"
        :data="deptTreeData"
        :props="{ label: 'deptName', children: 'children' }"
        node-key="id"
        check-strictly
        placeholder="部门"
        clearable
        class="w-44"
      />
      <ElSelect
        v-model="searchForm.positionCode"
        placeholder="岗位"
        clearable
        class="w-44"
      >
        <ElOption
          v-for="item in postOptions"
          :key="item.postCode"
          :label="item.postName"
          :value="item.postCode ?? ''"
        />
      </ElSelect>
      <ElButton type="primary" @click="handleSearch">查询</ElButton>
      <ElButton @click="handleReset">重置</ElButton>
    </div>
    <Grid table-title="用户管理">
      <template #toolbar-tools>
        <ElButton type="primary" @click="handleAdd">新增用户</ElButton>
      </template>
    </Grid>
    <UserFormModal @success="gridApi.query()" />
    <RoleAssignModal @success="gridApi.query()" />
  </Page>
</template>